INSERT IGNORE INTO categories (name, slug) VALUES ('Đời sống','doi-song');

INSERT IGNORE INTO articles (title, slug, summary, content, category_id, views, created_at) VALUES
('Thái Nguyên đẩy mạnh chuyển đổi số trong dịch vụ công', 'thai-nguyen-chuyen-doi-so-dich-vu-cong',
 'Nhiều thủ tục hành chính được thực hiện trực tuyến toàn trình, giúp người dân tiết kiệm thời gian đi lại.',
 'Các cơ quan hành chính trên địa bàn tỉnh tiếp tục mở rộng danh mục thủ tục được nộp hồ sơ trực tuyến.\nNgười dân có thể theo dõi tiến độ xử lý hồ sơ ngay trên điện thoại và nhận kết quả qua bưu điện.\nMục tiêu trong thời gian tới là nâng tỷ lệ hồ sơ trực tuyến và giảm thời gian giải quyết thủ tục.',
 (SELECT id FROM categories WHERE slug='thoi-su'), 210, NOW() - INTERVAL 6 DAY),
('Mưa lớn kéo dài, các địa phương chủ động phương án phòng chống ngập', 'mua-lon-phong-chong-ngap',
 'Lực lượng chức năng rà soát khu vực trũng thấp, sẵn sàng hỗ trợ người dân khi mưa lớn xảy ra.',
 'Theo dự báo, mưa lớn có thể kéo dài trong nhiều ngày tới tại khu vực miền núi phía Bắc.\nCác địa phương đã kiểm tra hệ thống thoát nước, khơi thông cống rãnh và cắm biển cảnh báo tại các điểm ngầm, tràn.\nNgười dân được khuyến cáo theo dõi bản tin thời tiết và hạn chế di chuyển qua khu vực nguy hiểm.',
 (SELECT id FROM categories WHERE slug='thoi-su'), 175, NOW() - INTERVAL 3 DAY),
('Trí tuệ nhân tạo hỗ trợ lập trình viên viết mã nhanh hơn', 'ai-ho-tro-lap-trinh-vien',
 'Các công cụ trợ lý lập trình giúp gợi ý mã, viết kiểm thử và giải thích lỗi ngay trong trình soạn thảo.',
 'Trợ lý lập trình dùng mô hình ngôn ngữ lớn đang được nhiều nhóm phát triển phần mềm sử dụng hằng ngày.\nCông cụ có thể đề xuất đoạn mã, viết kiểm thử đơn vị và giải thích thông báo lỗi khó hiểu.\nTuy vậy, lập trình viên vẫn cần đọc lại và kiểm tra kỹ mã được gợi ý trước khi đưa vào sản phẩm.',
 (SELECT id FROM categories WHERE slug='cong-nghe'), 320, NOW() - INTERVAL 5 DAY),
('Bảo mật website: vì sao cần HTTPS và security headers', 'bao-mat-website-https-security-headers',
 'HTTPS mã hóa dữ liệu trên đường truyền, còn security headers giúp trình duyệt chặn nhiều kiểu tấn công phổ biến.',
 'Khi website dùng HTTP thường, dữ liệu như mật khẩu có thể bị nghe lén trên đường truyền.\nHTTPS mã hóa toàn bộ kết nối, kết hợp HSTS để buộc trình duyệt luôn dùng kết nối an toàn.\nCác header như Content-Security-Policy, X-Frame-Options, X-Content-Type-Options giúp giảm nguy cơ XSS, clickjacking và MIME-sniffing.',
 (SELECT id FROM categories WHERE slug='cong-nghe'), 142, NOW() - INTERVAL 2 DAY),
('Log tập trung giúp quản trị viên phát hiện sự cố sớm', 'log-tap-trung-phat-hien-su-co',
 'Gom log của mọi dịch vụ về một nơi giúp tra cứu nhanh và tự động cảnh báo khi có dấu hiệu bất thường.',
 'Trong hệ thống nhiều dịch vụ, việc đăng nhập vào từng máy để đọc log tốn nhiều thời gian.\nCác giải pháp như Loki và Promtail thu gom log về một nơi, cho phép truy vấn bằng ngôn ngữ LogQL.\nKết hợp luật cảnh báo, quản trị viên có thể phát hiện tấn công dò mật khẩu chỉ sau vài chục giây.',
 (SELECT id FROM categories WHERE slug='cong-nghe'), 96, NOW() - INTERVAL 1 DAY),
('Sinh viên ICTU tham gia cuộc thi Olympic Tin học sinh viên', 'sinh-vien-ictu-olympic-tin-hoc',
 'Đội tuyển của trường đã trải qua nhiều tháng ôn luyện thuật toán và lập trình thi đấu.',
 'Đội tuyển gồm các sinh viên có thành tích tốt trong các kỳ thi lập trình cấp trường.\nTrong thời gian ôn luyện, các thành viên giải hàng trăm bài toán về cấu trúc dữ liệu và thuật toán.\nNhà trường kỳ vọng đội tuyển sẽ đạt kết quả tốt và lan tỏa phong trào học lập trình trong sinh viên.',
 (SELECT id FROM categories WHERE slug='giao-duc'), 188, NOW() - INTERVAL 4 DAY),
('Học kỳ mới: sinh viên được thực hành triển khai hệ thống trên Docker', 'thuc-hanh-trien-khai-docker',
 'Môn Triển khai và Quản trị Hệ thống Phần mềm giúp sinh viên làm quen quy trình vận hành thực tế.',
 'Sinh viên được thực hành đóng gói ứng dụng, cấu hình reverse proxy, giám sát và quản lý log.\nMỗi sinh viên thực hiện một đề tài riêng, quản lý mã nguồn trên GitHub theo từng mốc commit.\nKết quả được đánh giá qua buổi demo và báo cáo tổng hợp quá trình triển khai.',
 (SELECT id FROM categories WHERE slug='giao-duc'), 134, NOW() - INTERVAL 1 DAY),
('Giải bóng chuyền sinh viên khép lại với nhiều trận đấu hấp dẫn', 'giai-bong-chuyen-sinh-vien',
 'Giải đấu thu hút đông đảo sinh viên các khoa tham gia và cổ vũ.',
 'Sau hai tuần thi đấu, giải bóng chuyền sinh viên đã tìm ra nhà vô địch.\nNhiều trận đấu diễn ra kịch tính, phải phân định thắng thua ở set cuối cùng.\nBan tổ chức cho biết giải sẽ được duy trì hằng năm nhằm khuyến khích phong trào thể thao.',
 (SELECT id FROM categories WHERE slug='the-thao'), 87, NOW() - INTERVAL 7 DAY),
('Chạy bộ buổi sáng: thói quen nhỏ mang lại sức khỏe lớn', 'chay-bo-buoi-sang',
 'Chỉ 30 phút chạy bộ mỗi ngày giúp cải thiện sức bền, giấc ngủ và tinh thần làm việc.',
 'Chạy bộ là môn thể thao đơn giản, không cần nhiều dụng cụ và phù hợp với nhiều lứa tuổi.\nNgười mới bắt đầu nên khởi động kỹ, chạy chậm và tăng dần quãng đường theo tuần.\nUống đủ nước và chọn giày phù hợp giúp hạn chế chấn thương khi tập luyện.',
 (SELECT id FROM categories WHERE slug='the-thao'), 64, NOW() - INTERVAL 2 DAY),
('Thương mại điện tử tăng trưởng mạnh dịp cuối năm', 'thuong-mai-dien-tu-cuoi-nam',
 'Các sàn thương mại điện tử ghi nhận lượng đơn hàng tăng cao trong mùa mua sắm.',
 'Nhu cầu mua sắm trực tuyến tăng mạnh vào các dịp khuyến mãi lớn cuối năm.\nDoanh nghiệp đầu tư nhiều hơn vào kho vận và giao hàng nhanh để đáp ứng đơn hàng.\nNgười tiêu dùng được khuyến cáo kiểm tra kỹ thông tin người bán để tránh hàng kém chất lượng.',
 (SELECT id FROM categories WHERE slug='kinh-te'), 156, NOW() - INTERVAL 3 DAY),
('Doanh nghiệp nhỏ bắt đầu chuyển hạ tầng lên điện toán đám mây', 'doanh-nghiep-nho-len-dam-may',
 'Điện toán đám mây giúp doanh nghiệp giảm chi phí đầu tư máy chủ ban đầu.',
 'Thay vì mua máy chủ riêng, nhiều doanh nghiệp nhỏ thuê hạ tầng đám mây theo nhu cầu sử dụng.\nCách làm này giúp mở rộng hệ thống nhanh khi lượng khách hàng tăng.\nTuy nhiên doanh nghiệp cần chú ý sao lưu dữ liệu và cấu hình bảo mật đúng cách.',
 (SELECT id FROM categories WHERE slug='kinh-te'), 73, NOW() - INTERVAL 5 DAY),
('Mẹo sắp xếp thời gian học tập hiệu quả cho sinh viên', 'meo-sap-xep-thoi-gian-hoc-tap',
 'Lập kế hoạch theo tuần và chia nhỏ mục tiêu giúp sinh viên học đều, tránh dồn việc trước kỳ thi.',
 'Sinh viên nên ghi lại lịch học, lịch làm bài tập và hạn nộp vào một nơi duy nhất.\nChia công việc lớn thành nhiều phần nhỏ giúp dễ bắt đầu và theo dõi tiến độ.\nDành thời gian nghỉ ngơi hợp lý cũng quan trọng không kém việc học.',
 (SELECT id FROM categories WHERE slug='doi-song'), 119, NOW() - INTERVAL 2 DAY);
